module stack_tracking_min_max
fn put64(output &u8,mut pos int,value i64){bits:=u64(value);unsafe{for j in 0..8{output[pos]=u8((bits>>(8*j))&255);pos++}}}
@[export: 'stack_tracking_min_max']
pub fn stack_tracking_min_max(input &i64,length usize,output &u8,capacity usize) i64 {unsafe{if input==nil||length<2||length>130{return -1};max_size,count:=input[0],input[1];if max_size<0||max_size>64||count<0||count>64{return -1};mut p:=2;for _ in 0..int(count){if p>=int(length){return -1};op:=input[p];p++;if op==1{if p>=int(length)||input[p]< -2147483648||input[p]>2147483647{return -1};p++}else if op<2||op>5{return -1}};if p!=int(length){return -1};mut vals:=[64]i64{};mut mins:=[64]i64{};mut maxs:=[64]i64{};mut records:=[64][3]i64{};mut top:=0;mut rc:=0;p=2
 for _ in 0..int(count){op:=input[p];p++;mut tag:=i64(0);mut result:=i64(0);if op==1{x:=input[p];p++;if top==int(max_size){records[rc]=[3]i64{1,4,1};rc++;break};vals[top]=x;mins[top]=x;maxs[top]=x;if top>0{if mins[top-1]<x{mins[top]=mins[top-1]};if maxs[top-1]>x{maxs[top]=maxs[top-1]}};top++;tag=1;result=1}else if op==2{if top>0{top--;result=vals[top]}else{tag=3}}else if op==3{if top>0{result=mins[top-1]}else{tag=3}}else if op==4{if top>0{result=maxs[top-1]}else{tag=3}}else{tag=1;if top>0{result=1}};records[rc]=[3]i64{op,tag,result};rc++}
 need:=rc*24;if output==nil||capacity<usize(need){return -2};mut pos:=0;for i in 0..rc{for j in 0..3{put64(output,mut pos,records[i][j])}};return i64(pos)}}
